import{_ as a,o as l,c as r,a2 as e}from"./chunks/framework.BWuWLRhz.js";const u=JSON.parse('{"title":"快速开始","description":"从开通机构到第一节课打卡 —— AgoraIn v4 上手路径","frontmatter":{"title":"快速开始","description":"从开通机构到第一节课打卡 —— AgoraIn v4 上手路径"},"headers":[],"relativePath":"guide.md","filePath":"guide.md","lastUpdated":1791175900000}'),o={name:"guide.md"};function i(d,t,n,s,h,c){return l(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="快速开始" tabindex="-1">快速开始 <a class="header-anchor" href="#快速开始" aria-label="Permalink to &quot;快速开始&quot;">​</a></h1><p>整个过程分五步：<strong>开通机构 → 登录后台 → 建班级与学生 → 教室端签到 → 家长绑定</strong>。 考试阅卷是第五条链路，按需启用。</p><h2 id="一、开通机构-学校-培训机构" tabindex="-1">一、开通机构（学校 / 培训机构） <a class="header-anchor" href="#一、开通机构-学校-培训机构" aria-label="Permalink to &quot;一、开通机构（学校 / 培训机构）&quot;">​</a></h2><ol><li>打开平台地址 <a href="https://agorain.615mc.cn" target="_blank" rel="noreferrer">https://agorain.615mc.cn</a>，在登录页选择<strong>机构注册</strong></li><li>填写机构名称、管理员账号（邮箱 + 密码），完成邮箱验证码校验</li><li>注册成功后即创建一个<strong>独立区域</strong>；把区域名称或邀请链接发给平台方，获取 <strong>AGRR- 激活码</strong></li><li>在「授权管理」页输入激活码完成激活与续期</li></ol><div class="warning custom-block"><p class="custom-block-title">未激活区域限制</p><p>未激活的区域<strong>仅主账号可登录</strong>，其余成员无法登录，且受控功能（AI、阅卷、答题卡、设备注册、 课表、子用户、家长邀请）统一停用。</p></div><h2 id="二、登录后台" tabindex="-1">二、登录后台 <a class="header-anchor" href="#二、登录后台" aria-label="Permalink to &quot;二、登录后台&quot;">​</a></h2><ul><li>登录名格式：<strong><code>用户名@区域</code></strong>（主区域为 <code>@manager</code>，不写 <code>@</code> 时按主区域处理）</li><li>首次登录后进入控制台，左侧导航：仪表盘 / 班级 / 学生 / 设备 / 课时 / 通知 / 资源 / 试卷 / 答题卡 / 用户 / 授权 / 设置</li><li>管理员在「用户」页可以创建<strong>子账户</strong>并分配角色（owner / teacher），权限点矩阵统一控制</li></ul><h2 id="三、建班级、加学生" tabindex="-1">三、建班级、加学生 <a class="header-anchor" href="#三、建班级、加学生" aria-label="Permalink to &quot;三、建班级、加学生&quot;">​</a></h2><ol><li>「班级」→ 新建班级，设置年级与名称</li><li>「学生」→ 批量粘贴或逐个添加学生，可生成<strong>学号条码</strong></li><li>「学生」→ <strong>批量生成 6 位家长邀请码</strong>，导出 CSV 打印发放</li></ol><h2 id="四、教室端签到" tabindex="-1">四、教室端签到 <a class="header-anchor" href="#四、教室端签到" aria-label="Permalink to &quot;四、教室端签到&quot;">​</a></h2><ol><li>桌面端首次启动会进入<strong>向导</strong>：选择班级、网格行列、启动场景（大屏 / 控制 / 教师）与主题</li><li>大屏模式下，教师在后台创建<strong>签到码</strong>（教室 / 科目 / 签到密码 / 有效期）</li><li>学生用 App 扫码或输入短码签到 → 结果实时出现在大屏，前三名金 / 银 / 铜高亮</li><li>断网时大屏仍可本地打卡，网络恢复后自动同步</li></ol><blockquote><p>控制模式与教师模式默认内嵌服务端 Web 面板，课时、排课、点名等操作在同一个后台完成。</p></blockquote><h2 id="五、家长绑定" tabindex="-1">五、家长绑定 <a class="header-anchor" href="#五、家长绑定" aria-label="Permalink to &quot;五、家长绑定&quot;">​</a></h2><ol><li>家长微信搜索小程序，或在教师处扫描小程序码</li><li>选择「绑定孩子」，输入教师发放的 <strong>6 位邀请码</strong></li><li>绑定成功后可查看通知（带已读回执）、成绩概览（学校开启后可见）、值日安排与班级资源， 也可以直接给老师留言；多孩家庭可在「我的」中切换孩子</li></ol><h2 id="六、第一次考试-可选" tabindex="-1">六、第一次考试（可选） <a class="header-anchor" href="#六、第一次考试-可选" aria-label="Permalink to &quot;六、第一次考试（可选）&quot;">​</a></h2><ol><li>「试卷」→ 新建试卷 → 录入题型与分值；或<strong>文件导题</strong>（上传 docx / pdf 由 AI 识题）</li><li>「答题卡」标签页配置版面（纸型、考号类型、分区、栏数），预览后打印 <ul><li>也可按班级<strong>批量生成一人一张带条码</strong>的答题卡</li></ul></li><li>作答后拍照上传（App 或网页端「动态扫卡」，可接高拍仪）</li><li>客观题本机判分，主观题 AI 批改 → 教师在批改页逐题复判 → 确认出分</li><li>「成绩」页查看总分与得分率分析，需要时导出 CSV</li></ol><h2 id="七、常见配置" tabindex="-1">七、常见配置 <a class="header-anchor" href="#七、常见配置" aria-label="Permalink to &quot;七、常见配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>配置</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>AI 服务</td><td>后台 → AI 设置</td><td>可自配 API 地址与密钥（OpenAI 兼容协议）；也可使用平台额度</td></tr><tr><td>平台 AI 额度</td><td>后台 → AI 设置</td><td>兑换 AGRT- 额度码；自配密钥不受额度限制</td></tr><tr><td>图像外发开关</td><td>后台 → AI 设置</td><td>关闭后不向第三方发送任何作答图像</td></tr><tr><td>远程存储</td><td>服务端配置（运营方）</td><td>答题卡原图与资料 AES-256-GCM 加密上传 WebDAV</td></tr><tr><td>区域功能开关</td><td>主区域 → 区域管理</td><td>按区域开关 7 项能力</td></tr></tbody></table><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/features.html">功能特性</a> —— 完整能力清单</li><li><a href="/deploy.html">部署指南</a> —— 服务端、Web 面板、桌面端与移动端构建</li><li><a href="/faq.html">常见问题</a> —— 登录、激活、扫卡、AI 与存储的排查入口</li></ul>',20)])])}const b=a(o,[["render",i]]);export{u as __pageData,b as default};
